import { isPrimitive } from "./isPrimitive";
export const isObjectsEqualShallow = (elem1, elem2) => {
    const aProps = Object.keys(elem1);
    const bProps = Object.keys(elem2);
    if (aProps.length !== bProps.length) {
        return false;
    }
    for (const propName of aProps) {
        if (!isPrimitive(elem1[propName]) || !isPrimitive(elem2[propName])) {
            return false;
        }
        if (elem1[propName] !== elem2[propName]) {
            return false;
        }
    }
    return true;
};
